.wst-toc-dotcell {
	position:relative;
	width:100%;
}

/* Inner wrapper for the raw dot characters. */
.wst-toc-dotinner {
	display:inline;
	float:right;
	user-select:none;
}

/* Content part of dotcell */
.wst-toc-dotcell-content {
	display:inline;
	position:relative;
	background:var(--background-color-base, white);
    color: var(--color-base, #202122);
	z-index:2;
}

/* Outer wrapper for the raw dot characters. */
.wst-toc-dotouter {
	position:absolute;
	right:0px;
	bottom:0px;
	width:100%;
	overflow:hidden;
	white-space:nowrap;
	text-align:right;
	z-index:0;
}

/* That weird empty div before the dots. */
.wst-toc-dotempty {
	position:absolute;
	left:0;
	bottom:0;
	height:1em;
	z-index:1;
}

/* The part of a dotted cell containing actual content. */
.wst-toc-dotentry {
	display:inline;
	position:relative;
	text-align:left;
	padding:0 .5em 0 0;
	z-index:2;
}

