.wst-heading {
	text-align: center;
}

.wst-heading._ch-num {
	font-size: 120%;
	margin-top: 1em;
	margin-bottom: 1em;
}

.wst-heading._ch-title {
	font-variant: all-small-caps;
	margin-top: 1em;
	margin-bottom: 1em;
}


.wst-heading._sec-title {
    font-size: 110%;
	font-weight: bold;
	margin-top: 1em;
	margin-bottom: 0.5em;
}


.wst-heading._sec-subtitle {
	font-style: italic;
	margin-top: 1em;
	margin-bottom: 0.5em;
}

._toc {
	margin: 0 auto;
}

._toc ._toc-h td {
	font-size: 80%;
	font-variant: all-small-caps;
	text-align: right;
}

._toc td[colspan="2"] {
	text-align: center;
	padding-top: 1em;
	padding-bottom: 1em;
	font-size: 120%;
}

._toc ._toc-c {
	padding-top: 0.5em;
	padding-bottom: 0.5em;
}

._toc ._toc-c td:first-child { /* 2em hanging indent */
	padding-left: 2em;
	text-indent: -2em;
	overflow: hidden;
	position: relative;
}

._toc ._toc-c td:first-child::after {
	position: absolute;
	padding-left: 0.5em;
	word-spacing: 2em;
	content: ". . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .";
	text-align: right;
	text-indent: 0;
}

._toc ._toc-c td:nth-child(2) {
	text-align: right;
	vertical-align: bottom;
	padding-left: 1em;
}

._toc ._toc-d td {
	text-indent: 2em;
	font-size: 92%;
	padding-top: 0.5em;
	padding-bottom: 0.5em;
}

._toc .wst-plm {
	text-align: left;
	text-indent: 0;
	margin-right: 1em;
	width: 1em;
}
